import { Table } from './Table';

export const ShortcutTable = () => {
  const columns = [
    { title: 'Action', key: 'action' },
    { title: 'Keys', key: 'keys' },
  ];
  return <Table columns={columns} />;
};

import { motion } from 'framer-motion';

export function Steps({ children }) {
  const fade = { hidden: { opacity: 0 }, shown: { opacity: 1 } };
  return <motion.ul variants={fade} initial="hidden">{children}</motion.ul>;
}

import { useIntersection } from './useIntersection';

export function useVisible(ref) {
  const observerOptions = { rootMargin: '0px', threshold: 0.5 };
  return useIntersection(ref, observerOptions);
}

import * as React from 'react';
import { loadReport } from '../api';

export default function Report() {
  const query = { status: 'open', limit: 20 };
  const [rows, setRows] = React.useState([]);
  React.useEffect(() => {
    loadReport(query).then(setRows);
  }, [query]);
  return <ul>{rows.length}</ul>;
}

import Editor from '@monaco-editor/react';

export function QueryEditor({ value }: { value: string }) {
  function registerLanguage(monaco: any) {
    monaco.languages.register({ id: 'query' });
  }
  return <Editor value={value} beforeMount={registerLanguage} />;
}

import { memo } from 'react';
import { List } from './List';
import { formatName } from './format';

export const People = memo(function People({ people }: { people: string[] }) {
  const renderItem = (person: string) => <span>{formatName(person)}</span>;
  return <List items={people} renderItem={renderItem} />;
});

import { useCallback } from 'react';
import { Grid } from './Grid';

export const Board = ({ onPick }: { onPick: (s: string) => void }) => {
  const sizes = ['small', 'large'] as const;
  const pick = useCallback((s: string) => onPick(s), [onPick, sizes]);
  return <Grid sizes={sizes} onPick={pick} />;
};

import { useCreateEvent } from './useCreateEvent';
import { toast } from '../toast';

export function CreateDialog() {
  const onError = (message: string) => {
    toast(message, 'error');
  };
  const { form } = useCreateEvent(onError);
  return form;
}

import * as R from 'react';
import { loadWeek } from '../api';

export function Weekly() {
  const range = { days: 7 };
  const [rows, setRows] = R.useState([]);
  R.useEffect(() => {
    loadWeek(range).then(setRows);
  }, [range]);
  return <ol>{rows.length}</ol>;
}

import React from 'react';
import { loadMonth } from '../api';

const { useEffect, useState } = React;

export function Monthly() {
  const range = { days: 30 };
  const [rows, setRows] = useState([]);
  useEffect(() => {
    loadMonth(range).then(setRows);
  }, [range]);
  return <ol>{rows.length}</ol>;
}

import { PlanGrid } from './PlanGrid';

export function Plans({ showPlans }: { showPlans: boolean }) {
  if (showPlans) {
    const plans = [{ id: 'free' }, { id: 'pro' }];
    return <PlanGrid plans={plans} />;
  }
  return null;
}

import { Table } from './Table';

export function Results({ compact }: { compact: boolean }) {
  const compactColumns = [{ key: 'name' }];
  const fullColumns = [{ key: 'name' }, { key: 'owner' }];
  return <Table columns={compact ? compactColumns : fullColumns} />;
}

import { Select, type Option } from './Select';

export function Country() {
  const countries = [{ value: 'fr', label: 'France' }];
  return <Select options={countries as Option[]} />;
}

import { Picker } from './Picker';

export function Currency() {
  const currencies = ['USD', 'EUR', 'JPY'];
  const first = [...currencies].sort()[0];
  return <Picker items={currencies} initial={first} />;
}

import { Picker } from './Picker';

export function Sizes() {
  const sizes = ['s', 'm', 'l'];
  const largestFirst = sizes.slice().reverse();
  return <Picker items={sizes} order={largestFirst.join()} />;
}

import { ThemeContext } from './context';

export function ThemeRoot({ children }) {
  const theme = { dark: true };
  return <ThemeContext.Provider value={theme}>{children}</ThemeContext.Provider>;
}

import { logger } from './logger';
import { Button } from './Button';

export function Filters() {
  const onPress = () => logger.info('pressed');
  return <Button onPress={onPress} />;
}

import { format } from './format';
import { Table } from './Table';

export function Filters() {
  const columns = [{ key: 'date', render: (v) => format(v) }];
  return <Table columns={columns} />;
}

