export function LabelledSelect() {
  const options = [{ value: 'a', label: t('Option A') }];
  return <Select options={options} />;
}

import { Table } from './Table';

export function Dropped({ fields }: { fields: string[] }) {
  const rows = [];
  for (const field of fields) {
    rows.push({ field });
  }
  return <Table rows={rows} />;
}

import { Badge } from './Badge';

export function Summary({ op }: { op: string }) {
  const ops = ['+', '-', '*'];
  const levels = { low: 1, high: 2 };
  return <Badge>{ops.includes(op) ? levels.high : levels.low}</Badge>;
}

export function Panel({ children }) {
  const style = { display: 'flex', gap: 8 };
  const onClick = () => console.info('panel');
  return <div style={style} onClick={onClick}>{children}</div>;
}

import { Button } from './Button';

export function Actions() {
  const common = { size: 'sm', variant: 'ghost' };
  return <Button {...common}>Save</Button>;
}

import { useRef, useState } from 'react';

export function useDraft() {
  const initial = { title: '', body: '' };
  const [draft, setDraft] = useState(initial);
  const seen = useRef(initial);
  return { draft, setDraft, seen };
}

import { useState } from 'react';
import { KeyList } from './KeyList';

export function Keys() {
  const [keys] = useState(() => {
    const fallbackKeys = ['a', 'b'];
    return fallbackKeys;
  });
  return <KeyList keys={keys} />;
}

import { Input } from './Input';

export function makeField(name: string) {
  return function Field() {
    const rules = { required: true };
    return <Input name={name} rules={rules} />;
  };
}

import { useState } from 'react';
import { Modal } from './Modal';

export function Dialog() {
  const [open, setOpen] = useState(false);
  const onClose = () => setOpen(false);
  return <Modal open={open} onClose={onClose} />;
}

import { Canvas } from './Canvas';

export function Viewport() {
